import { Button, Section, Text } from '@react-email/components';
import { Layout, buttonStyle, infoBoxStyle, infoLineStyle, noteStyle } from './Layout';

interface CertificateReadyEmailProps {
  name: string;
  rollNumber: string;
  practiceArea: string;
  certificateUrl: string;
  // Issued by the team with the PDF attached (vs. generated by the student)
  attached?: boolean;
}

export function CertificateReadyEmail({ name, rollNumber, practiceArea, certificateUrl, attached = false }: CertificateReadyEmailProps) {
  return (
    <Layout previewText="Your LexAssess certificate is ready" heading="Your Certificate Is Ready">
      <Text>Hi {name},</Text>
      <Text>
        {attached
          ? 'Congratulations! Your LexAssess certificate is attached to this email as a PDF.'
          : 'Your LexAssess certificate has been generated and is ready to view or download.'}
      </Text>
      <Section style={infoBoxStyle}>
        <Text style={infoLineStyle}>
          <strong>Roll Number:</strong> {rollNumber}
        </Text>
        <Text style={infoLineStyle}>
          <strong>Practice Area:</strong> {practiceArea}
        </Text>
      </Section>
      <Button href={certificateUrl} style={buttonStyle}>
        {attached ? 'Verify Your Certificate' : 'View Your Certificate'}
      </Button>
      <Text style={noteStyle}>
        {attached
          ? 'Anyone can confirm this certificate by scanning its QR code or opening the link above.'
          : 'Log in to your LexAssess account to view or download your certificate at any time.'}
      </Text>
    </Layout>
  );
}
